<?php ac_hero('Executive overview','Arena command dashboard','Launch readiness, watchpoints, source gates, timeline distribution, and next owner actions for the July 25, 2026 Interlochen-focused launch.'); $cards=require __DIR__.'/../data/dashboard_cards.php'; ?><section class="metrics"><?php foreach($cards as $c) ac_metric($c['label'],$c['value'],$c['note']); ac_metric('Normalized records',(string)count($records),'SSOT-derived and placeholder-derived'); ac_metric('Public blocked',(string)count(array_filter($records,fn($r)=>ac_public_gate($r)==='blocked')),'Gate visible by record'); ?></section><section class="grid two"><article class="panel"><h2>Launch watchpoints</h2><?php ac_checklist(['Migrate docs/cue.txt draft into reviewed Timeline Registry rows','Approve rights before any public website or marketing use','Clear venue-dependent fog/strobe/rig safety before show-ready promotion','Keep tribute-safe copy: no official affiliation, endorsement, sponsorship, licensing, or protected marks']); ?></article><article class="panel"><h2>Next actions</h2><?php ac_record_cards(array_slice(ac_filter_records(fn($r)=>preg_match('/needs|proposed|draft/i',$r['status'].' '.$r['rights_status'].' '.$r['safety_status'])),0,4)); ?></article></section><section class="panel"><h2>Module status grid</h2><div class="module-grid"><?php foreach($navigation as $n){ if(!empty($n['hidden'])) continue; echo '<a class="module-card" href="?page='.ac_e($n['id']).'"><b>'.ac_e($n['label']).'</b><span>'.ac_e($n['summary']).'</span></a>'; } ?></div></section>
